"""Reproducible analysis pipeline generated by Avaloka.

Mission goal: how does depth vary by hydro_zone
This script reproduces the data preparation performed during the Avaloka
mission. It is dependency-light (pandas only) and deterministic.
"""

import pandas as pd

DATA_SOURCE = 'C:\\Users\\Hrishi\\Desktop\\projects\\Gujarat Monsoon gap\\data\\processed\\gujarat_groundwater_analytical.csv'


# The strings read as missing, per column, exactly as the analysis read them.
MISSING_STRINGS = {
    **dict.fromkeys(['slno', 'state_lgd_code', 'district_lgd_code', 'latitude', 'longitude', 'rl_msl', 'data_collection_date', 'depth', 'year', 'month'], ['', '#N/A', '#N/A N/A', '#NA', '-1.#IND', '-1.#QNAN', '-NaN', '-nan', '1.#IND', '1.#QNAN', '<NA>', 'N/A', 'NA', 'NULL', 'NaN', 'None', 'n/a', 'nan', 'null']),
    **dict.fromkeys(['station_name', 'agency', 'state', 'district', 'tehsil', 'block', 'village', 'river', 'basin', 'tributary', 'subtributary', 'subsubtributary', 'local_river', 'hydro_zone', 'season', 'station_code'], ['']),
}


def load() -> pd.DataFrame:
    df = pd.read_csv(
        DATA_SOURCE, sep=',', encoding='utf-8', keep_default_na=False, na_values=MISSING_STRINGS)
    return df.dropna(axis=1, how="all")  # all-empty columns, as the analysis dropped them

def transform(df: pd.DataFrame) -> pd.DataFrame:
    """Apply the transformations Avaloka selected for this dataset."""
    df = df.drop(columns=['state_lgd_code', 'state', 'river', 'basin', 'tributary', 'subtributary', 'subsubtributary', 'local_river'])  # constant columns
    for _c in ['station_name', 'agency', 'district', 'tehsil', 'block', 'village', 'data_collection_date', 'hydro_zone', 'season', 'station_code']:
        df[_c] = df[_c].astype('string').str.strip()
    return df


def main() -> None:
    df = load()
    print("Loaded:", df.shape)
    df = transform(df)
    print("Transformed:", df.shape)
    df.to_parquet("transformed_dataset.parquet", index=False)
    print("Wrote transformed_dataset.parquet")


if __name__ == "__main__":
    main()
